        });
    }

    pub fn set_default_font(&mut self, font: DefaultFont, names: Vec<String>) {
        self.mutate_with_update_context(|context| {
            context.library.set_default_font(font, names);
        });
    }

    pub fn fetch(
        &self,
        mut request: Request,
        fetch_reason: FetchReason,
    ) -> OwnedFuture<Box<dyn SuccessResponse>, ErrorResponse> {
        match self.compatibility_rules.block_or_rewrite_swf_url(
            request.url().into(),
            UrlRewriteStage::BeforeRequest,
            fetch_reason,
        ) {
            Ok(Some(new_url)) => request.set_url(new_url),
            Ok(None) => {}
            Err(error) => return Box::pin(async move { Err(error) }),
        }

        let self_reference = self.self_reference.clone();
        let fetch = self.navigator.fetch(request);
        Box::pin(async move {
            let response = fetch.await;

            let Ok(mut response) = response else {
                return response;
            };

            let Some(player) = self_reference.upgrade() else {
                return Ok(response);
            };

            let new_url = player
                .lock()
                .unwrap()
                .compatibility_rules
                .block_or_rewrite_swf_url(
                    response.url(),
                    UrlRewriteStage::AfterResponse,
                    fetch_reason,
                )?;
            if let Some(new_url) = new_url {
                response.set_url(new_url);
            }

            Ok(response)
        })
    }
}

impl Drop for Player {
    fn drop(&mut self) {
        self.flush_shared_objects();
    }
}

/// Player factory, which can be used to configure the aspects of a Ruffle player.
pub struct PlayerBuilder {
    movie: Option<SwfMovie>,

    // Backends
    audio: Option<Box<dyn AudioBackend>>,
    log: Option<Box<dyn LogBackend>>,
    navigator: Option<Box<dyn NavigatorBackend>>,
    renderer: Option<Box<dyn RenderBackend>>,
    storage: Option<Box<dyn StorageBackend>>,
    ui: Option<Box<dyn UiBackend>>,
    video: Option<Box<dyn VideoBackend>>,
    locale: Option<Box<dyn LocaleBackend>>,

    // Notifications
    notification_sender: Option<Sender<PlayerNotification>>,

    // Misc. player configuration
    autoplay: bool,
    align: StageAlign,
    forced_align: bool,
    scale_mode: StageScaleMode,
    forced_scale_mode: bool,
    allow_fullscreen: bool,
    fullscreen: bool,
    letterbox: Letterbox,
    max_execution_duration: Duration,
    viewport_width: u32,
    viewport_height: u32,
    viewport_scale_factor: f64,
    load_behavior: LoadBehavior,
    spoofed_url: Option<String>,
    compatibility_rules: CompatibilityRules,
    gamepad_button_mapping: HashMap<GamepadButton, KeyCode>,
    player_version: Option<u8>,
    player_runtime: PlayerRuntime,
    player_mode: PlayerMode,
    quality: StageQuality,
    page_url: Option<String>,
    frame_rate: Option<f64>,
    external_interface_provider: Option<Box<dyn ExternalInterfaceProvider>>,
    fs_command_provider: Box<dyn FsCommandProvider>,
    #[cfg(feature = "known_stubs")]
    stub_report_output: Option<std::path::PathBuf>,
    avm2_optimizer_enabled: bool,
    #[cfg(feature = "default_font")]
    default_font: bool,
}

impl PlayerBuilder {
    /// Generates the base configuration for creating a player.
    ///
    /// All settings will be at their defaults, and "null" backends will be used. The settings
    /// can be changed by chaining the configuration methods.
    #[inline]
    pub fn new() -> Self {
        Self {
            movie: None,

            audio: None,
            log: None,
            navigator: None,
            renderer: None,
            storage: None,
            ui: None,
            video: None,
            locale: None,

            notification_sender: None,

            autoplay: false,
            align: StageAlign::default(),
            forced_align: false,
            scale_mode: StageScaleMode::default(),
            forced_scale_mode: false,
            allow_fullscreen: true,
            fullscreen: false,
            // Disable script timeout in debug builds by default.
            letterbox: Letterbox::Fullscreen,
            max_execution_duration: Duration::from_secs(if cfg!(debug_assertions) {
                u64::MAX
            } else {
                15
            }),
            viewport_width: 550,
            viewport_height: 400,
            viewport_scale_factor: 1.0,
            load_behavior: LoadBehavior::Streaming,
            spoofed_url: None,
            compatibility_rules: CompatibilityRules::default(),
            gamepad_button_mapping: HashMap::new(),
            player_version: None,
            player_runtime: PlayerRuntime::default(),
            player_mode: PlayerMode::default(),
            quality: StageQuality::High,
            page_url: None,
            frame_rate: None,
            external_interface_provider: None,
            fs_command_provider: Box::new(NullFsCommandProvider),
            #[cfg(feature = "known_stubs")]
            stub_report_output: None,
            avm2_optimizer_enabled: true,
            #[cfg(feature = "default_font")]
            default_font: true,
        }
    }

    /// Configures the player to play an already-loaded movie.
    #[inline]
    pub fn with_movie(mut self, movie: SwfMovie) -> Self {
        self.movie = Some(movie);
        self
    }

    /// Sets the audio backend of the player.
    #[inline]
    pub fn with_audio(mut self, audio: impl 'static + AudioBackend) -> Self {
        self.audio = Some(Box::new(audio));
        self
    }

    /// Sets the audio backend of the player.
    #[inline]
    pub fn with_boxed_audio(mut self, audio: Box<dyn AudioBackend>) -> Self {
        self.audio = Some(audio);
        self
    }

    /// Sets the logging backend of the player.
    #[inline]
    pub fn with_log(mut self, log: impl 'static + LogBackend) -> Self {
