    names += ['scaleX', 'scaleY']
q = {n: i + 1 for i, n in enumerate(names)}
cp = u(1) + u(1) + u(1) + u(len(strings)) + b''.join(u(len(s.encode())) + s.encode() for s in strings[1:])
cp += u(3) + bytes([0x16]) + u(0) + bytes([0x16]) + u(si['flash.display']) + u(1)
